// 在线运行演示：Java（服务端沙箱执行，入口类必须为 Main）
public class Main {
    public static void main(String[] args) {
        int[] nums = {3, 1, 4, 1, 5, 9, 2, 6};
        int max = nums[0];
        long sum = 0;
        for (int n : nums) {
            if (n > max) {
                max = n;
            }
            sum += n;
        }
        System.out.println("Hello from Java on the server!");
        System.out.println("最大值 = " + max + " | 平均值 = " + String.format("%.2f", (double) sum / nums.length));
        System.out.println("sqrt(2) = " + String.format("%.4f", Math.sqrt(2)));
    }
}

