// 在线运行演示：C（服务端沙箱执行）
#include <stdio.h>

int main(void) {
    int nums[] = {3, 1, 4, 1, 5, 9, 2, 6};
    int n = sizeof(nums) / sizeof(nums[0]);
    int max = nums[0];
    long sum = 0;
    for (int i = 0; i < n; i++) {
        if (nums[i] > max) {
            max = nums[i];
        }
        sum += nums[i];
    }
    puts("Hello from C on the server!");
    printf("最大值 = %d | 平均值 = %.2f\n", max, (double) sum / n);
    return 0;
}

