#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>
#include <cmath>
#include <iomanip>

int main() {
    std::vector<int> nums{3, 1, 4, 1, 5, 9, 2, 6};
    int max = *std::max_element(nums.begin(), nums.end());
    double avg = std::accumulate(nums.begin(), nums.end(), 0.0) / nums.size();
    std::cout << "Hello from C++ on the server!" << std::endl;
    std::cout << "最大值 = " << max << " | 平均值 = " << std::fixed << std::setprecision(2) << avg << std::endl;
    std::cout << "sqrt(2) = " << std::setprecision(4) << std::sqrt(2.0) << std::endl;
    return 0;
}
